script:
export const meta = {
  name: 'wayne-code-review-flow',
  description: 'Formal static gate over one already-committed range: freeze base..head -> two independent voices (Claude + GPT) in parallel on shared criteria -> attributed synthesis -> PASS/FAIL. Portable across repos.',
  phases: [{ title: 'Freeze' }, { title: 'Review' }, { title: 'Synthesize' }],
};

// --- params (all optional) ---------------------------------------------------
const base = (args && args.base) ? String(args.base) : '';
const CLAUDE = (args && args.claudeModel) || 'amd-internal-anthropic/Claude-Opus-5';
const GPT = (args && args.gptModel) || 'openai-amd/gpt-5.6-sol';

// --- 1. Freeze the target: one immutable patch + sha256, same bytes for both -
phase('Freeze');
const freezeScript = `
set -e
base='${base}'
if [ -z "$base" ]; then
  printf '{"error":"NO_RANGE"}\\n'
  exit 0
fi
# Uncommitted work is not in the range, so a report over the range would describe
# something other than what is on disk. Refuse instead of reviewing an unnameable target.
dirty="$(git status --porcelain | head -20)"
if [ -n "$dirty" ]; then
  printf '{"error":"DIRTY_WORKTREE","paths":"%s"}\\n' "$(echo "$dirty" | tr '\\n' ';')"
  exit 0
fi
gitdir="$(git rev-parse --absolute-git-dir)"
dir="$gitdir/wcr"
mkdir -p "$dir"
out="$dir/freeze.patch"
lo="$(printf '%s' "$base" | sed 's/\\.\\..*$//')"
hi="$(printf '%s' "$base" | sed 's/^.*\\.\\.//')"
[ -n "$lo" ] || lo="$base"
if [ "$hi" = "$lo" ] || [ -z "$hi" ]; then hi="HEAD"; fi
base_sha="$(git rev-parse --verify "$lo^{commit}")"
head_sha="$(git rev-parse --verify "$hi^{commit}")"
git diff --binary --full-index "$base_sha" "$head_sha" > "$out"
if [ ! -s "$out" ]; then
  printf '{"error":"EMPTY_RANGE","base_sha":"%s","head_sha":"%s"}\\n' "$base_sha" "$head_sha"
  exit 0
fi
commits="$(git rev-list --count "$base_sha".."$head_sha")"
sha="$(sha256sum "$out" | cut -d' ' -f1)"
bytes="$(wc -c < "$out")"
printf '{"patchPath":"%s","sha256":"%s","bytes":%s,"base_sha":"%s","head_sha":"%s","commits":%s}\\n' "$out" "$sha" "$bytes" "$base_sha" "$head_sha" "$commits"
`;
const freezeOut = await agent(
  `Run this EXACT bash and return ONLY the final JSON line it prints on stdout, nothing else:\n\n\`\`\`bash\n${freezeScript}\n\`\`\``,
  { model: CLAUDE, phase: 'Freeze' },
);

const jm = freezeOut.match(/\{[\s\S]*\}/);
if (!jm) return `wayne-code-review-flow: FREEZE FAILED — no JSON from freeze step.\n\n${freezeOut}`;
let frozen;
try { frozen = JSON.parse(jm[0]); } catch (e) { return `wayne-code-review-flow: FREEZE FAILED — bad JSON: ${e}\n\n${freezeOut}`; }
const REFUSALS = {
  NO_RANGE: "no review range given. Name the PR or commit range to review, e.g. base='main..HEAD'. Guessing a base is how a gate silently covers the wrong commits.",
  DIRTY_WORKTREE: `uncommitted or untracked files present, so the range does not describe the tree: ${frozen.paths || ''}. Commit or stash them first.`,
  EMPTY_RANGE: `range ${frozen.base_sha || ''}..${frozen.head_sha || ''} contains no changes.`,
};
if (frozen.error) return `wayne-code-review-flow: GATE: FAIL \u2014 ${REFUSALS[frozen.error] || frozen.error}`;
const bytes = Number(frozen.bytes || 0);
if (!bytes) return `wayne-code-review-flow: GATE: FAIL \u2014 frozen patch is empty.`;
const patchPath = frozen.patchPath;
const sha = frozen.sha256;
const range = `${frozen.base_sha}..${frozen.head_sha} (${frozen.commits} commit(s))`;

// --- 2. Two heterogeneous voices, parallel, independent ----------------------
const reviewPrompt = (voice) => `You are an independent static code reviewer (voice: ${voice}).

CRITERIA
- Read ~/.agents/skills/wayne-code-review/references/reviewer-protocol.md with the read tool and follow it exactly. It is the single source of the review criteria, and every voice in this run receives that same file.
- If it cannot be read, stop and return {"voice":"${voice}","error":"PROTOCOL_UNREADABLE"}. Never review without the criteria.

FROZEN TARGET
- Patch file: ${patchPath}  (sha256=${sha}, range=${range})
- Read that file with the read tool. Review ONLY the changes in this patch.
- You MAY read/grep surrounding code in the repo for evidence/context.
- READ-ONLY. Do not edit, write, or run any mutating command.
- You have NOT seen any other reviewer's output. Judge independently.

OUTPUT — return ONLY this JSON object, no prose:
{
  "voice": "${voice}",
  "patch_sha256": "${sha}",
  "verdict": "NO FINDINGS" | "FINDINGS",
  "findings": [
    { "severity": "CRITICAL"|"INFORMATIONAL", "confidence": 1-10,
      "category": "security|dataflow|architecture|concurrency|performance|tests|api-migration|general",
      "file": "<repo-relative path>", "line": <number>,
      "problem": "<one sentence>", "evidence": "<concrete proof>", "fix": "<recommended change>" }
  ]
}
"NO FINDINGS" requires findings=[].`;

phase('Review');
const [claudeRaw, gptRaw] = await parallel([
  () => agent(reviewPrompt('claude'), { model: CLAUDE, phase: 'Review' }),
  () => agent(reviewPrompt('gpt'), { model: GPT, phase: 'Review' }),
]);

// --- 3. Synthesize with attribution + gate -----------------------------------
phase('Synthesize');
const synthPrompt = `You are the synthesizer for a dual-voice static review. Two INDEPENDENT reviewers of different model families examined the SAME frozen patch (sha256=${sha}, range=${range}).

=== VOICE A (Claude / ${CLAUDE}) RAW ===
${claudeRaw}

=== VOICE B (GPT / ${GPT}) RAW ===
${gptRaw}

TASK
1. Deduplicate by causal MECHANISM + affected behavior, not by line alone.
2. Attribute each finding: AGREEMENT (both voices independently), CLAUDE-ONLY, GPT-ONLY,
   or CONTRADICTION (mark UNRESOLVED; give both positions, pick no winner).
3. Keep original confidence; +1 (cap 10) only when dual independent evidence agrees.
4. Recompute counts from the raw artifacts. Invent nothing not present in either voice.
5. If a voice returned malformed/empty output, say so — never treat provider failure as "NO FINDINGS".

GATE
- FAIL on any unresolved CRITICAL, any CONTRADICTION affecting correctness/safety/compatibility/intent,
  and on any voice that returned PROTOCOL_UNREADABLE, malformed output, or nothing at all.
- PASS only with two valid voices, no unresolved blocker, consistent counts.

OUTPUT: markdown with sections Verdict, Patch, Counts (severity x source), Agreements,
Claude-only, GPT-only, Contradictions(UNRESOLVED), Runtime boundary.
End with EXACTLY one final line: "GATE: PASS" or "GATE: FAIL".`;

const report = await agent(synthPrompt, { model: CLAUDE, phase: 'Synthesize' });

const t = report.trim();
const gate = /GATE:\s*PASS\s*$/.test(t) ? 'PASS'
  : /GATE:\s*FAIL\s*$/.test(t) ? 'FAIL'
  : 'INDETERMINATE (no gate line — treat as FAIL)';
log(`wayne-code-review-flow gate: ${gate}`);

return `# wayne-code-review-flow — gate: ${gate}

Frozen: ${patchPath} (sha256=${sha})
Range: ${range} | ${bytes} bytes
Voices: Claude=${CLAUDE} | GPT=${GPT} (parallel, independent)

${report}

---
This is the formal static gate: one frozen patch, two independent model families,
attributed synthesis, one explicit verdict. It does NOT run the application —
wayne-verify owns runtime proof, so GATE: PASS is necessary but not sufficient to ship.`;
